    faq_a_shop_holidays: "В списке покупок нажмите на подарок: по порядку появятся праздники вашей страны (указанной в Настройках) с датами – они сами рассчитываются каждый год. Нажмите на праздник, чтобы открыть готовый список того, что к нему обычно покупают; всё уже выбрано (кроме того, что уже есть в вашем списке), снимите отметку с ненужного и нажмите «Добавить в список». За две недели до праздника вверху списка появляется маленькая карточка; ✕ скрывает её до следующего праздника.",
    faq_q_shop_holidays: "Как работает «Что купить к празднику»?",
    shop_hol_add: "Добавить в список ({n})",
    shop_hol_added: "Добавлено в список: {n}",
    shop_hol_btn: "Что купить к празднику",
    shop_hol_items_title: "{holiday} – что купить?",
    shop_hol_not_now: "Не сейчас",
    faq_a_shop_delivery: "В списке покупок нажмите на грузовик: выберите, что в доставке (выбрано всё), когда её привезут – сегодня, завтра или в другой день – и в какое время (утро, день, вечер или «Другое…», чтобы указать свои часы). Эти товары переходят в карточку «В пути» вверху списка, с указанием дня и часов. Когда наступает этот день, в «Моём дне» появляется «Доставку привезли?» (а на карточке – «Привезли?»). Если привезли всё, товары переходят в «Купить снова». Если чего-то не хватает, нажмите на то, чего не привезли, и это сразу вернётся в список.",
    faq_a_shop_departments: "Список сам сортируется по отделам супермаркета – овощи и фрукты, хлеб, молочные продукты и яйца, мясо и рыба, бакалея, заморозка, напитки, снеки, бытовая химия, гигиена, товары для малышей и зоотовары, – чтобы вы проходили ряды по порядку. Отдел определяется по названию товара. Если товар попал не туда, нажмите на него и выберите отдел или «Другое…», чтобы написать свой.",
    faq_a_shop_share_qty: "Да. Рядом с каждым товаром + добавляет ещё один (×2, ×3…), а − убирает один. Кнопка «Поделиться» вверху списка покупок отправляет весь список, аккуратно разложенный по отделам, в WhatsApp, по эл. почте или как копию.",
    faq_a_shop_two_buttons: "Обе кнопки значат «куплено». ✕ – для того, что покупается один раз: товар уходит из списка (и ждёт в архиве 🗑️ на случай ошибки). ↺ – для того, что покупается снова и снова: товар уходит из списка и ждёт в «Купить снова» – его открывает маленькая кнопка ↺ рядом с мусорной корзиной внизу списка, и одно нажатие там возвращает товар в список. В «Изменить» внутри можно убрать из него товар. Когда вы добавляете товар, то, что вы уже покупали, появляется в подсказках, а если он уже есть в списке, он просто становится ×2 вместо второй строки.",
