    nm_demo_saved_2: "Йогурт с гранолой и фруктами",
    nm_demo_title: "Как работает замена",
    faq_a_new_me_challenge_journal: "Когда челлендж заканчивается – большой, мини-челлендж или челлендж недели, – в поздравлении есть кнопка 📝 Как прошло? Она открывает страницу в дневнике челленджей: каково было (пять лиц), что помогло, что было трудно и что взять с собой дальше – ничего из этого не обязательно, и всё можно отложить на потом. Дневник – это бриллиант в волшебном рюкзаке: каждый завершённый челлендж с датой и тем, что было написано, новые сверху – нажмите на любой, чтобы прочитать, изменить его или поделиться им (отправляется только то, что есть на странице). Завершённый челлендж также получает медаль в достижениях, в разделе «Пройденные челленджи». Дневник челленджей отделён от обычного дневника.",
    faq_q_new_me_challenge_journal: "Что такое дневник челленджей?",
