    nm_chj_share_text: "Челлендж в New Me пройден ✨",
    nm_chj_take: "Что взять с собой дальше?",
    nm_chj_title: "Дневник челленджей",
    nm_chj_write: "Написать, как прошло",
    nm_swap_time: "Время",
    faq_a_ai_reminder_in_text: "Да – напишите его вместе с задачей, например «завтра в 17:00 забрать посылку, с напоминанием за час». Напоминание сохраняется в самой задаче: за час, за полчаса, за день и так далее, а «напомни мне» без времени означает за 10 минут. Напоминание, написанное в тексте, имеет приоритет над полем напоминания в том же окне.",
    faq_q_ai_reminder_in_text: "Можно ли попросить ИИ-ассистента о напоминании в том же запросе?",
    myday_meals_all_done: "Все приёмы пищи на сегодня отмечены 🍽️",
    nm_tour_week_text: "Небольшой челлендж на неделю. ✓ каждый день – а в конце ключ.",
    books_home_chip: "{title} · стр. {page}",
    books_home_of: "из {total}",
    books_home_off_toast: "Книга убрана с главного экрана",
    books_home_on_toast: "Книга на главном экране 📖",
    books_home_pin: "На главном экране",
    books_home_q: "На какой я странице?",
    books_home_save: "Сохранить",
    faq_a_books_home_chip: "Да. В «Уголке чтения» на карточке книги, которую вы читаете, коснитесь 📌 На главном экране. Под приветствием на главном экране появится маленькая кнопка с книгой и страницей – коснитесь её, введите новый номер страницы и сохраните, и прогресс будет записан (в «Уголке чтения» тоже). Повторное касание 📌 убирает её. Можно закрепить сразу несколько книг – по кнопке на каждую, – и на всех устройствах всё одинаково.",
    faq_a_new_me_week_challenge: "Небольшой челлендж на одну неделю, который вы выбираете сами. В коридоре есть большая карточка: «Над чем хочется поработать на этой неделе?» – коснитесь её, выберите область (с собой, с другими, учиться и расти, спокойствие, маленькие смелые шаги, дом и распорядок) и челлендж, а затем выберите, когда он начнётся. Те же челленджи есть и на экране челленджей, в разделе 🌱 Личностный рост. Каждый день на карточке ставится ✓ (один свободный день в неделю), а каждая завершённая неделя приносит новый ключ для тайного мира. «Читать 2 страницы в день» отмечается сам по страницам, записанным в «Уголке чтения». Когда неделя заканчивается, 📌 Оставить как ежедневную задачу добавляет его в «Мой распорядок» в выбранное время, с ✓ каждый день. Одновременно идёт только один челлендж недели; большие и мини-челленджи продолжаются рядом с ним.",
    faq_a_room_genie: "На веранде у моря касание лампы Аладдина вызывает лесного духа – и начинается разговор: какое у вас желание (что хочется изменить в жизни), какие будут ощущения, когда оно исполнится, что трудно на пути и как нынешнюю ситуацию можно обратить во благо. Потом – сколько это примерно займёт времени, первый маленький шаг и ещё два, и «если… то…» на случай, когда станет трудно. В конце всё желание появляется шаг за шагом, и его можно превратить в цель в «Моих целях» (шаги станут этапами на пути, с датой по выбранному сроку; там всё можно изменить) или сохранить в дневнике – и тогда дух прощается. Ничего не сохраняется, если не выбрать одно из двух. Со второго визита дух сначала спрашивает, хотите ли вы изменить в жизни что-то ещё: да – тот же разговор; не сейчас – напоминание достигать уже поставленных целей. Дух выходит раз в день: после того как желание сохранено (или после «Не сейчас»), он отдыхает до завтра. Вопросы построены по известному способу превращать желание в план: желание, результат, препятствие и план.",
    faq_q_books_home_chip: "Можно ли видеть свою книгу и страницу на главном экране?",
