    room_sign_text: "Забота о себе",
    room_game_tag: "По пути – остановиться и насладиться",
    room_drawer_aria: "Шкафчик",
    nm_me_choose: "Выбрать",
    nm_me_on_screen: "На экране",
    faq_a_new_me_game: "В New Me игровые кнопки всегда остаются на одном месте – в коридоре, в тайной комнате и везде в лесу; меняется только картина в центре. Вверху: день пути, ключи, серия и энергия на сегодня (сколько съедено из плана), а под ними – следующее задание: следующий приём пищи в своё время (нажатие открывает его, с ✓ Съедено). Сбоку: весь день, челленджи и мой путь, а рядом с ними – челлендж недели: его 7 дней и ✓ на сегодня. Внизу: волшебный рюкзак (всё в New Me – карта мира, мой путь, список покупок, достижения, дневник челленджей, замеры, фото прогресса, календарь месяца, таблица за день, напоминания, меню в PDF и настройки; он открывается как отдельный экран). Карта мира, которая лежит в рюкзаке первой, показывает все места в лесу – нажмите на место, чтобы перейти туда; на закрытом месте видно, сколько ключей нужно. Me – ваш персонаж на тропинке в лесу: он начинает как Me1, после нескольких челленджей (4 ключа) вырастает в Me2, а ближе к концу (9 ключей) – в Me3, с преображением прямо на глазах. Нажмите на Me, чтобы увидеть все этапы – любого уже достигнутого персонажа можно выбрать снова, так что прежний может вернуться. Me парит: его перетаскивают пальцем или мышью, и вход, которого он коснётся, открывается (на закрытом написано, скольких ключей не хватает). Me также приходит с вами в каждую комнату и каждое место и парит там, где вы его оставите: перетащите его куда угодно, а светящееся кольцо под ним потяните, чтобы полностью повернуть его вокруг своей оси; он смотрит в ту сторону, куда движется (на компьютере: стрелки двигают его, Q и E поворачивают). В коридоре маленький значок 🏠 под верхней панелью возвращает на главный экран; в каждой комнате и каждом месте кнопка в том же углу возвращает в коридор.",
    faq_q_new_me_game: "Как работают игровые кнопки, карта мира и Me?",
