    room_magic_song_rec2: "Лунная арфа",
    room_magic_song_rec3: "Колокольчики водопада",
    faq_a_new_me_menu_build: "Сначала анкета спрашивает, какие у вас приёмы пищи и когда (2 приёма пищи + перекус, 2 приёма пищи + лёгкий ужин или и то и другое), и есть ли что-то вечером – поесть или попить, что именно и во сколько. При «2 приёма пищи + перекус» это обед (11:30) и ужин (19:00), а перекус – в 16:00. Затем появляются все варианты для этих приёмов пищи. Выберите до 2 любимых на каждый приём пищи – в меню будет написано «это или то». В некоторых вариантах (пита с пастой, кукурузные хлопья с молоком, что-нибудь лёгкое) вы выбираете до 3 любимых продуктов, каждый в своей порции, и в меню будет «это или то или другое»; калории считаются по выбранному. С кофе и напитками – так же. Каждый выбор сбалансирован, так что день складывается ровно в 1300 или 1500. Чтобы изменить в любой момент: ⚙️ Настройки → 🍽️ Составьте меню или «Выберите до 3 любимых» в карточке приёма пищи.",
