    faq_a_myday_water_toggle: "Да. Стакан воды в «Моём дне» (с + для ещё одного стакана) показывается по умолчанию. Чтобы скрыть его, выключите «Показывать воду в „Моём дне“» в Настройках > Персонализация и календарь. Ничего не удаляется – «Учёт воды» продолжает работать, а при повторном включении стакан возвращается.",
    faq_q_myday_water_toggle: "Можно ли скрыть воду в «Моём дне»?",
    myday_water_toggle_label: "Показывать воду в «Моём дне»",
    faq_a_routine_newme_sync: "С New Me в ⚙️ «Моего распорядка» есть переключатель «Синхронизация с New Me». Когда он включён (по умолчанию), сегодняшние приёмы пищи New Me видны в «Моём дне» и в «Моём распорядке» – вместо скрытых приёмов пищи распорядка. Когда выключен, приёмы пищи New Me уходят из обоих мест, а распорядок становится точно таким, как был. Ничего не удаляется – повторное включение всё возвращает и спрашивает, какие приёмы пищи в распорядке скрыть.",
