    theme_name_watercolor_wash: "Акварель",
    faq_a_food_list_languages: "Встроенный список продуктов создавался с израильскими блюдами и их названиями на иврите. На всех остальных языках каждый продукт показан под английским названием, а поиск находит любое известное ему английское название (например, 'broth' находит Clear soup); продукты, у которых есть только название на иврите, в списке не показываются. Всё, чего нет в списке, можно просто написать своими словами – оценка с помощью ИИ работает на любом языке.",
    faq_q_food_list_languages: "Почему в списке продуктов на моём языке английские названия и меньше продуктов?",
    settings_copyright_line: "© 2026 все права защищены. приложение разработано eden zabari.",
    workout_ready_replace_btn: "Заменить",
    faq_a_sport_workout_ai: "В «Мои тренировки» → ⋯ → «План с ИИ» (а когда таблица пуста — ещё и на плитке рядом с готовыми планами). Ответьте парой касаний: сколько раз в неделю, когда, место, уровень и цель — почти везде есть и «Другое», — и при желании добавьте свободную строку, например про чувствительное колено или пробежку 5 км к лету. ИИ составит целую неделю: виды тренировок, дни, время, длительность, интенсивность, упражнения и дни отдыха. До сохранения показывается предпросмотр: «В мою таблицу» (вместо таблицы или в дополнение к ней), «Другой вариант» (до 3 раз) или «Изменить ответы». План намеренно умеренный, а если упомянуть боль или травму, будут мягкие варианты и совет посоветоваться со специалистом. Он расходует ту же квоту ИИ, что и расписание с распорядком: 5 раз бесплатно и 60 в месяц с Премиум.",
    faq_q_sport_workout_ai: "Как составить план тренировок с ИИ?",
    workout_ai_add: "В дополнение к таблице",
    workout_ai_again: "Другой вариант",
    workout_ai_apply: "В мою таблицу",
