    workout_ai_edit: "Изменить ответы",
    workout_ai_failed: "Не удалось составить план – попробуйте ещё раз",
    workout_ai_freq_label: "Сколько раз в неделю",
    workout_ai_freq_ph: "Тренировок в неделю",
    workout_ai_go: "Составить план",
    workout_ai_goal_fitness: "Общая форма",
