    faq_a_new_me_magic_themes: "Пять сверкающих тем, которые входят в New Me: «Волшебный лес», «Звёздная пыль», «Фея роз», «Волшебное сияние» и «Золотой закат». Выберите одну внутри New Me (⚙️ Настройки > Цвета) или в Настройках > Внешний вид и экран, и кисть с блёстками раскрасит ею экран. Волшебная тема добавляет блёстки по всему приложению и при каждом касании. Вернуться к любой другой теме можно в любой момент.",
    faq_q_new_me_magic_themes: "Что такое волшебные темы New Me?",
