    quotes_look_bookmarks: "Закладки",
    quotes_look_polaroid: "Фото",
    quotes_look_title: "Вид цитат",
    quotes_look_wall: "Стена",
    theme_magic_section_label: "Волшебные темы New Me",
    apptour_focus_text: "Всё уходит в сторону, кроме одного дела на сейчас – с большой ✓. Затем появляется следующее.",
    apptour_m_presets_text: "Ваши сохранённые блюда в одном месте: поиск, недавние, по времени дня – а ＋ добавляет блюдо на сегодня.",
    apptour_night_text: "🌙 делает всё приложение тёмным, ☀️ возвращает день.",
    apptour_noteline_text: "Напишите и нажмите ➤ – это сохранится в заметках. 📝 в начале строки переключает на 🛒 покупки или 🍎 сохранённое блюдо.",
    apptour_search_text: "Заметки, покупки, календарь, рецепты, тетради, цели, таблицы и книги – один поиск находит всё.",
    faq_a_new_me_ai_menu: "Перед меню анкета спрашивает, какие у вас приёмы пищи и когда (2 приёма пищи + перекус, 2 приёма пищи + лёгкий ужин или и то и другое), бывает ли что-то небольшое вечером и во сколько, чего вы не едите и как пьёте кофе или чай. Затем ИИ составляет 3 варианта для каждого приёма пищи – каждый по размеру его доли дня, так что день по-прежнему складывается ровно в 1300 или 1500 – и идеи напитков, которые сохраняются как ваши постоянные напитки. Выберите до 2 любимых вариантов на каждый приём пищи; варианты исходного меню – прямо под ними, а в 🔄 Замене они идут после личного меню. 🔄 Другие варианты составляет новый набор (3 раза за анкету). Чтобы изменить ответы или составить новое меню в любой момент: ⚙️ Настройки → ✨ Личное меню (ИИ).",
    faq_q_new_me_ai_menu: "Как работает личное меню в New Me?",
    nm_ai_menu_building: "Составляем меню под ваши приёмы пищи и время…",
    nm_ai_menu_drinks: "Напитки для вас",
    nm_ai_menu_error: "Сейчас не получилось составить личное меню – вот исходное меню. Можно попробовать ещё раз или позже в ⚙️ Настройки.",
    nm_ai_menu_original: "Из исходного меню",
