    settings_sub_status_newme: "Премиум входит в ваш New Me.",
    room_back_to_shelf: "К полке",
    faq_a_new_me_day_total: "Каждый день складывается ровно в план: приёмы пищи, около 150 ккал на кофе и напитки в течение дня и то, что выбрано на вечер, – что-нибудь маленькое поесть или что-нибудь попить. На вечер выберите до 3 любимых (например, банан, йогурт или 2 дольки тёмного шоколада; или травяной чай, чай с капелькой молока или тёплое молоко), и их калории берутся из приёмов пищи. Каждый выбор уравновешивается сам: вариант поменьше или побольше, убранный приём пищи, лёгкий завтрак и небольшой приём пищи, который к нему добавляется, или вечер – разница добавляется к приёмам пищи или вычитается из них, к каждому по его размеру, и под каждым написано, сколько (+ или −) и что добавить или убрать. Уже отмеченный приём пищи остаётся таким, как был записан. В анкете у каждого приёма пищи виден его сдвиг, а маленькая рамка показывает приёмы пищи, напитки, вечер и итог. Хочется в этот день чего-то другого? Главное – держать итог в той же калорийности или меньше.",
