    books_quotes_chip: "Цитаты",
    faq_a_book_quotes: "На полке в тайной комнате (Цитаты) или через маленький значок 💬 Цитаты в Уголке чтения – это один и тот же список. Нажмите «+ Цитата», напишите строку и выберите книгу из Уголка чтения или введите другое название через «✏️ Другое»; автор не обязателен. ✏️ изменяет цитату, 🗑️ удаляет её. Цитаты — это закладки, которые листаются свайпом: 🎨 вверху переключает на фото или стену карточек.",
    faq_a_room_wish_jar: "На полке в тайной комнате стоит стеклянная банка для мечтаний. Нажмите на маленькую банку на верхней полке (или Полка > Банка желаний) и напишите, какой вы хотите видеть свою жизнь – смело, без «правильно» и «неправильно». Каждое желание складывается в записку и падает в банку. «Вытянуть записку» открывает случайную, а каждую записку можно открыть и отдельно. Со второго раза, когда вы открываете одно и то же желание, его можно сделать целью и разбить на маленькие шаги. Раз в неделю мягко появляется записка с одним из ваших желаний – без давления, просто напоминание, куда вы идёте.",
