    faq_a_saved_meals_page: "У сохранённых блюд есть своя страница: Питание и показатели > ⭐ Сохранённые блюда (или ⭐ в меню). Поиск вверху находит блюдо по названию или ингредиенту, «Недавние» показывает, что вы добавляли в последнее время, а вкладки (Завтрак, Обед, Ужин, Супы…) — каждое время дня. «+ На сегодня» добавляет блюдо в сегодняшний Дневник питания, в следующую свободную ячейку. Нажмите на блюдо, чтобы изменить или удалить его, а ＋ вверху добавляет новое.",
