    presets_tab_sweet: "Сладкое",
    faq_a_notes_sticky_look: "Заметки — это короткий список стеклянных карточек: 🎨 вверху заметок меняет вид всех заметок (списка, кнопок дней вверху и окна, где пишется заметка): стекло, чистый список, карточки или скотч. Перетаскиваемая заметка сохраняет точно свой вид и цвет. Нажмите на текст заметки, чтобы открыть её: там можно её изменить, поменять цвета и увидеть, когда она была написана в последний раз. Нажмите ○, когда дело сделано, а × отправляет её в архив (🗑️ внизу списка возвращает её). Перетащите за ⠿, чтобы изменить порядок, под «Позже» или на день вверху. ! отмечает заметку как срочную – она плавно поднимается в первые строки с маленькой меткой «Срочно»; повторное нажатие снимает отметку.",
    faq_q_notes_sticky_look: "Как открыть, изменить или убрать заметку?",
    note_to_archive_btn: "В архив",
    faq_a_routine_clash: "Если в это время в те же дни уже есть пункт, появятся два варианта: «Заменить» – новый пункт занимает это время, а для прежнего выбирается другое (при редактировании существующего пункта предлагается его прежнее время, и они просто меняются местами), или «Оба» – оба остаются в одно и то же время, один под другим. Если дни разные (например, один с воскресенья по четверг, а другой в пятницу), ничего не спрашивается.",
    faq_q_routine_clash: "Что будет, если поставить пункт распорядка на уже занятое время?",
