    faq_a_new_me_coffee: "Под сегодняшним меню есть короткая сводка: сколько калорий во всех приёмах пищи за день, сколько осталось на кофе и напитки, и кнопки выбранных кофе и напитков – одно нажатие добавляет в «Напитки». В «Выберите до 3 любимых» под кнопками (и в анкете) выбирается, что показывать: вода / газированная вода, травяной чай, диетическая газировка, чёрный / американо (~5), чай с капелькой молока (~25), кофе на воде с молоком или растительным молоком до 100 мл (~50), лёгкое какао, тёплое молоко или обычный кофе / латте (~120).",
