    nm_late_room_line: "Что-нибудь маленькое перед сном · на сегодня осталось ~{n} ккал",
    faq_a_recipe_examples: "Под вашими рецептами есть примеры: завтраки, салаты, супы, основные блюда, гарниры, перекусы, десерты и веганские блюда. У каждого указаны время приготовления, калории на порцию и сколько граммов весит одна порция. Нажмите на рецепт, чтобы открыть его, а кнопка «Сохранить в мои рецепты» создаст вашу копию, которую можно редактировать. Метки категорий фильтруют, а повторное нажатие на ту же метку снова показывает всё.",
    faq_a_recipe_grams: "В рецепте рядом с калориями написано «1 порция ≈ X г». В своих рецептах заполните «Граммов в порции» (и, если хотите, время приготовления) в форме рецепта — оба поля необязательны, а время показывается на цветной полосе рецепта.",
