    recipe_saved_example_toast: "Сохранено в моих рецептах — там его можно изменить",
    recipes_examples_title: "Примеры рецептов",
    faq_a_recipe_scan_multi: "Да. В «Добавить рецепт» нажмите 📷 и выберите одно фото или несколько (до 6; подойдёт и PDF). Каждое появится в коротком списке, где нужно выбрать, что на нём: Всё, Ингредиенты или Приготовление, а «➕ Ещё фото» добавляет новые. Затем нажмите «✨ Сканировать рецепт»: ИИ соберёт всё в один рецепт по порядку и без повторов, и это считается одним сканированием. Несколько фото, выбранных в 📷 Фото в ИИ-помощнике, тоже открываются здесь.",
    faq_q_recipe_scan_multi: "Можно ли отсканировать один рецепт по нескольким фото, например ингредиенты и шаги отдельно или две страницы?",
