    faq_a_note_written_at: "Нажмите на текст заметки, чтобы открыть её. Внутри, под текстом, видно, когда она была написана в последний раз, с точной датой и временем. Это обновляется только при изменении самого текста: архив и восстановление, отметка ✓, цвета или перемещение заметки этого не меняют.",
    faq_q_note_written_at: "Как узнать, когда была написана заметка?",
    note_written_at: "Последний раз написано: {date}",
    faq_a_new_me_month: "В волшебном рюкзаке → «Календарь месяца»: каждый день окрашен по количеству отмеченных приёмов пищи, стрелки ‹ › листают месяцы, а под календарём указаны средние калории в день за месяц. Нажатие на день показывает, сколько приёмов пищи отмечено и сколько калорий съедено в этот день.",
    faq_q_new_me_month: "Где посмотреть прошлые дни месяца и средние калории в New Me?",
