    nm_extra_line_small: "{n} ккал к этому приёму пищи – от маленького завтрака, например {ideas}",
    faq_a_new_me_small_breakfast: "Лёгкий завтрак (около 170 ккал): пита из полбы (до 100 ккал) с пастой или сыром, плюс овощ – выберите до 3 любимых, например 1 ч. л. шоколадной пасты, 1 ч. л. арахисовой пасты или ломтик твёрдого сыра (до 22%). Поскольку он небольшой, к нему добавляется «И ещё небольшой приём пищи» в другое время (через полтора часа, например 11:30 → 13:00 – можно выбрать любое другое время): ещё пита с пастой, протеиновый йогурт и фрукт, рисовые хлебцы с сыром, хлопья с молоком или половина питы и яйца – примерно до 200 ккал, со своей галочкой ✓. Всё, что ещё остаётся, делится между остальными приёмами пищи, и у каждого видно, сколько ему добавилось, так что итог дня остаётся как в плане. Его можно выбрать в анкете или поменять на него только на сегодня через 🔄 – например, когда завтракаете поздно.",
    faq_q_new_me_small_breakfast: "Что такое «маленький завтрак» в меню New Me?",
