    weather_sky_snow: "Снег",
    weather_sky_storm: "Гроза",
    faq_a_ai_icon: "Да – в Настройках > Внешний вид и экран. По умолчанию это мягкий пузырь, а с Premium можно выбрать ещё парящий мозг или робота.",
    faq_a_new_me_favorites: "Да. В анкете (и при повторном прохождении из настроек) можно выбрать до 2 вариантов для каждого приёма пищи. Первый показывается в меню, а под ним строка «или» со вторым – нажатие на неё меняет на него только на сегодня. А если завтрак не съеден вовремя, «⏰ Позже» переносит его на потом в течение дня, не меняя калорий.",
    faq_a_theme_mode: "Некоторые особые темы лучше всего смотрятся в тёмном режиме – Акварель, Северное сияние, Барби и обе темы с блёстками, – поэтому выбор одной из них включает тёмный режим, а выбор любой другой темы (и ракеты тоже) – светлый. Чёрная и Тёмно-серая остаются тёмными. Потом всегда можно переключить через 🌙 в меню или «Светлый режим» в настройках.",
    faq_a_water_month: "В учёте воды. У каждой записи в журнале за сегодня указано время, когда она добавлена, а «Таблица за месяц» открывает весь месяц: в каждом дне видно, сколько литров выпито (✓, когда дневная цель достигнута), а нажатие на день показывает его записи со временем.",
