    faq_a_new_me_weight_optional: "Нет. И текущий, и целевой вес в анкете необязательны. Если позже добавить взвешивание (⚖️ Вес в разделе «Мой путь» в New Me или в трекере веса), прогресс считается от первого из них.",
    faq_q_new_me_weight_optional: "Обязательно ли указывать вес в New Me?",
