    faq_a_room_records: "Проигрыватель стоит в комнате с самого начала, на пне у кресла. Его пластинки открывают на YouTube официальные клипы больших хитов последних лет, а под ними – пять спокойных мелодий, которые звучат прямо в комнате: пластинка крутится, пока они играют, а «⏹ Стоп» выключает музыку.",
    faq_a_room_roof_gifts: "Они появляются с 8-м ключом. Касание телескопа позволяет заглянуть в него: ночное небо вблизи – перетаскивайте (или используйте стрелки), чтобы осмотреться, – и завершённые челленджи складываются в нём в созвездие, по звезде на каждый; касание звезды показывает, какой это был челлендж. Касание маленького сундука открывает его – пока он пуст – а ещё одно касание закрывает.",
    faq_q_room_records: "Что есть на проигрывателе в тайной комнате?",
