    faq_a_ai_chat_food_fix: "Да. Под ответом в чате коснитесь ✏️ Исправить калории / белок, измените числа и нажмите «Сохранить». Меняется только то, что было только что добавлено, – даже если это присоединилось к уже существующему перекусу. ИИ может ошибаться, поэтому стоит быстро проверить.",
    faq_a_new_me_home_btn: "Если у вас есть New Me, маленький 💎 рядом с режимом фокуса вверху главного экрана открывает меню на сегодня. Сегодняшние приёмы пищи видны и в «Моём дне», у каждого есть ✓.",
    faq_a_routine_item_days: "Да. Коснитесь пункта в «Мой распорядок» и выберите его дни в 📅 Дни – например, только с понедельника по пятницу. В остальные дни он не показывается в «Мой день» и у него нет ✓; в «Мой распорядок» он остаётся, бледнее, с днями рядом. Карточка, которая спрашивает о пункте после 3 дней без ✓, считает только дни этого пункта.",
    faq_q_ai_chat_food_fix: "Можно ли исправить калории или белок после того, как помощник записал еду?",
