    nm_times_hint: "Совет: можно указать самое позднее время, когда вы обычно едите каждый приём пищи, — например, 9:00, если вы часто едите около 8.",
    room_game_marquee: "По пути – остановиться и насладиться",
    room_sand_erase_aria: "Потрите, чтобы стереть надпись",
    faq_a_home_note_line: "Напишите в строке посередине главного экрана и нажмите ➤ (или Enter) — заметка сохранится в «Заметках». Нажмите 📝 в начале строки, и он станет 🛒: тогда написанное попадёт в список покупок. Нажмите ещё раз — 🍎: введите несколько букв, появятся подходящие сохранённые блюда, и одно нажатие запишет блюдо в сегодняшние приёмы пищи. С 🎤 можно просто сказать вслух.",
    faq_a_night_mode: "Откройте меню ☰ и нажмите 🌙 вверху — всё приложение станет тёмным. ☀️ на том же месте вернёт день. Это есть и в Настройках, в пункте «Светлый режим».",
    faq_q_home_note_line: "Как написать быструю заметку с главного экрана?",
    faq_q_night_mode: "Как включить ночной режим?",
    menu_day_mode: "Дневной режим",
    menu_night_mode: "Ночной режим",
    faq_a_secret_room_yoga: "В конце тропинки в лесу стоят светящиеся ворота, а за ними, у водопада, лесные жители – Луми, Пуффи, Никси и Спарклет – сидят полукругом на своих ковриках, а напротив них на единственном коврике на камне сидит Флора, учительница йоги. Коснитесь Флоры – она открывает глаза, всё приближается, и разговор начинается неспешно, с временем на чтение: Флора спрашивает, как у всех дела, каждый житель отвечает под своим именем (рядом с каждой строкой – маленький рисунок того, кто говорит), а потом она спрашивает вас, как вы себя чувствуете с близкими людьми. Разговор идёт по вашим ответам: хорошие люди, кто-то, с кем трудно, или немного одиночества. Каждый путь заканчивается маленькой миссией (её можно сразу добавить в «Мой день»; если миссия – что-то написать, для этого есть место, и написанное сохраняется в волшебном дневнике) и позой с тремя вдохами вместе. ↩ возвращает на шаг назад, а ✦ начинает новый разговор. Следующий ключ открывает водопад: если сесть на камень, всё исчезает и остаётся только шум воды. Если склониться над прудом, из воды поднимается вопрос – что сделало бы сегодня ваше настоящее «я»? – и ответ становится маленьким делом в «Моём дне». Это тёплый момент, а не замена разговору со специалистом.",
