    faq_a_new_me_times: "В анкете в начале и в любой момент в настройках New Me → «Время приёмов пищи». Если в распорядке уже есть время для еды, оно берётся оттуда – и приёмы пищи распорядка можно скрыть, а на их месте показать приёмы пищи New Me. Если нет – выберите, сколько приёмов пищи в день (2 приёма пищи + перекус / 2 приёма пищи + лёгкий ужин / 2 приёма пищи + перекус + лёгкий ужин) и когда каждый. При «2 приёма пищи + перекус» это обед в 11:30, перекус в 16:00 и ужин в 19:00 (любое время можно изменить). Это ваше время еды везде: в коридоре, в «Моём дне», в «Моём распорядке» и в напоминаниях. Что бы ни выбрать, калорийность дня остаётся прежней: то, что убрано, делится между остальными приёмами пищи.",
    faq_q_new_me_times: "Как задать время приёмов пищи в New Me?",
