    routine_daysoff_pick_days: "Выберите хотя бы один день",
    routine_daysoff_what: "А какой распорядок в эти дни?",
    routine_daysoff_which: "Какие дни?",
    faq_a_secret_room_diary: "Только вы. Страницы дневника сохраняются в аккаунте, поэтому они есть на всех устройствах, и больше никто их не видит. Дневник открывается с волшебного дневника на столе в тайной комнате, а также с дневника в музыкальном уголке. Под новой страницей — свёрнутая таблица месяца: точка отмечает каждый день, в котором есть страница, а касание дня открывает его страницы; там же можно удалить страницу. Когда дневник уже открыт, его можно добавить и в главное меню – переключателем в самом дневнике или в настройках New Me.",
    faq_a_secret_room_places: "Каждый вход у лесных ворот открывается своим ключом. За ними: веранда у моря (на маленьком столике – лампа Аладдина: одно касание, и из неё в волшебном тумане поднимается лесной дух, кружится и начинает разговор о вашем желании – см. «Что делает джинн из лампы?»), гитара и дневник (гитара играет короткую спокойную мелодию и затихает сама, а каждая из трёх пластинок, висящих на дереве, играет свою волшебную мелодию, повторное касание останавливает её, а в дневнике на пне можно писать), комната дыхания (тихое озеро на закате; на воде плывёт лотосовый фонарик: коснитесь его, напишите желание, и он уплывает с ним далеко вглубь озера; волшебной палочкой можно написать на песке то, что хочется отпустить, и надпись останется, пока вы не сотрёте её пальцем) и тропинка в лесу (она открывается ночью, а касание фонарей переключает на день; на большой ветке висят волшебные качели, на скамейке можно посидеть, а касание вывески приближает её: доска с шестью маленькими вопросами, которые можно отметить). На закрытом входе видно, сколько ключей осталось. В конце тропинки светящиеся ворота ведут к йоге у водопада, а оттуда — к самому водопаду.",
    faq_q_secret_room_diary: "Кто видит дневник?",
