    ai_chat_working_schedule: "Минутку, добавляю в календарь…",
    ai_chat_working_table: "Минутку, создаю таблицу…",
    dev_weather_preview_label: "Предпросмотр – только в вашем аккаунте:",
    faq_a_ai_chat: "Нажмите на пузырёк – откроется чат. Выберите, что сделать – что-то в календарь, что съедено, фото рецепта или новую таблицу – или просто напишите, и ассистент сам поймёт. Для календаря можно выбрать один раз, каждую неделю или каждый день. Ответ приходит в чат, а оттуда можно перейти к чему-то ещё или открыть календарь / съеденное.",
    faq_a_new_me_hall: "New Me открывается у ворот волшебного леса, и каждый вход в нём – это место: круглая дверь в огромном дереве ведёт в тайную комнату, полое бревно – на веранду у моря, домик-гриб – к гитаре и дневнику, маленькая ивовая арка – в комнату дыхания, большая ивовая арка – на тропинку в лесу, а цветочная арка с лестницей ведёт наверх, на звёздную крышу, когда та откроется. На закрытом входе висит замок. На тропинке парит ваш персонаж, Me, а вокруг – игровые кнопки: следующее задание, челлендж недели, волшебный рюкзак со всем New Me, карта мира и инструменты. Нажатие на ключи вверху объясняет, как зарабатываются ключи.",
    faq_a_new_me_routine_meals: "Когда в New Me заданы приёмы пищи, а в «Моём распорядке» тоже есть приёмы пищи, New Me спрашивает, скрыть ли их и показать на их месте приёмы пищи New Me – чтобы ничего не показывалось дважды. Тогда «Мой распорядок» показывает приёмы пищи New Me в их время, с 💎 и ✓; нажатие на название приёма пищи открывает окно выбора другого приёма пищи или изменения его времени прямо там, поверх распорядка. Ничего не удаляется: они возвращаются через ⚙️ Настройки New Me → Приёмы пищи в распорядке или если выключить «Синхронизация с New Me» в ⚙️ «Моего распорядка». Без активного New Me они возвращаются сами.",
    faq_a_room_computer: "Это маленький чат, который начинается с вопроса «Как проходит ваш день?» – хорошо, загруженно или тяжело – и идёт с вами шаг за шагом, до одной маленькой миссии в конце (её можно сразу отправить в «Мой день»). На ответы можно нажимать или писать свободно – написанное связывается с ближайшим ответом. «↩ Назад» возвращает на шаг, чтобы ответить иначе, а «Новый чат» начинает заново в любой момент. После загруженного или тяжёлого дня можно вернуться к компьютеру позже в тот же день: «Я снова здесь...» продолжает разговор. Зелёный огонёк внизу выключает и включает компьютер. Сохраняются только выборы, только на этом устройстве и только до конца дня.",
