    pcx_c_end1: "Стоит помнить: тяжёлый день – это не тяжёлая жизнь, а всего лишь одна страница целой книги. Завтра новый день.",
    pcx_c_end2: "Спокойного, мягкого вечера. А если нужно будет выговориться ещё или позже станет тяжело – я здесь. Просто возвращайтесь, и поговорим.",
    pcx_c_o1: "Физически плохо / дикая усталость",
