    pcx_c_o4: "Просто тяжесть на душе, без явной причины",
    pcx_c_q: "Ох, грустно это слышать... такие дни могут правда вымотать. Дню можно быть таким, и это совершенно нормально. Хотите поделиться, что сегодня тяготит больше всего?",
    pcx_cr1_s: "Совершенно нормально, что это не исчезло по взмаху волшебной палочки. Такие дни нужно просто пройти с минимальными усилиями. Не боритесь с чувством – просто дайте этому дню спокойно закончиться.",
    pcx_cr2_o1: "🌬️ 5 вдохов вместе",
    pcx_cr2_o2: "✍️ Написать 3 предложения",
