    pcx_cr3_s: "Всё обязательно будет хорошо. У вас уже были трудные дни, и вы через них прошли, и этот день тоже почти закончился. Вы сделали сегодня всё, что могли, и этого совершенно достаточно. Обнимаю! 🤗",
