    dictation_mic_denied: "Микрофон заблокирован — разрешите его через 🔒 рядом с адресом в браузере или в настройках телефона",
    faq_a_dictation: "Да – нажмите на микрофон 🎤 в углу быстрой заметки или страницы для письма в тетради и говорите: слова пишутся по ходу речи, на языке приложения. Нажмите ещё раз, чтобы остановить. В первый раз браузер попросит разрешение на микрофон. Работает в Chrome / Android и в Safari на iPhone. На компьютере нужен микрофон и браузер вроде Chrome, Edge или Safari; если чего-то не хватает, сообщение скажет, чего именно.",
    faq_q_dictation: "Можно говорить вместо того, чтобы печатать?",
    faq_a_secret_room: "Комната только для вас в New Me – дом внутри огромного дерева. Видна одна стена за раз, а повернуться можно стрелками (или свайпом). Первый ключ приходит после ✓ на приёме пищи в 3 разных дня и открывает дверь – а вместе с ней всю комнату: компьютер, игру, проигрыватель, полку с библиотекой внутри и кошку. Дальше каждый завершённый челлендж (и челлендж недели тоже) даёт ключ, который открывает следующее место: звёздную крышу, веранду у моря, гитару и дневник, комнату дыхания, тропинку в лесу с йогой, водопад и сюрприз на крыше – а 8-й приносит бутылку из моря с письмом из прошлого внутри. Когда что-то открывается, стрелка показывает путь к нему. Открывается и маленькая дверца внизу игрового автомата – пока шкафчик за ней пуст. На звёздной крыше звезда, которой коснулись, падает, как падающая звезда, а кошка сидит на подушке.",
