    room_wall_window_title: "Окно и компьютер",
    faq_a_steps_in_sport: "Вверху раздела «Отслеживание тренировок», в маленькой полоске: шаги за сегодня и за неделю. Шаги будут считаться автоматически, когда приложение подключится к Google Fit / Apple Health в версии для телефона, – об этом рассказывает кнопка 🔗 рядом.",
    faq_q_steps_in_sport: "Где счётчик шагов за день?",
    sport_steps_today_label: "шагов сегодня",
    sport_steps_week_label: "за неделю",
    faq_a_reminders_one_place: "Каждое напоминание приходит один раз и в одно место. Если приложение открыто перед вами (на компьютере, iPad или телефоне), оно появится там; иначе придёт уведомлением только на телефон. «✅ Готово, спасибо!» или «Понятно!» в любом месте закрывает его на всех устройствах, и оно не вернётся. «Ещё нет» откладывает его: оно возвращается каждые 5 минут, каждый раз в одно место. Отметка ✓ у задачи в списке тоже считается «готово». Чтобы получать уведомления и на компьютере и планшете, включите «Также на компьютере и планшете» в разделе Настройки > Уведомления.",
    faq_q_reminders_one_place: "Почему напоминание приходит только один раз и только на телефон?",
    reminder_all_devices_hint: "По умолчанию каждое напоминание приходит один раз и в одно место: на телефон или на устройство, где приложение открыто прямо перед вами. «Готово» или «Понятно» в одном месте закрывает его везде.",
    reminder_all_devices_label: "Также на компьютере и планшете",
    myday_water_info: "8 средних / небольших стаканов воды — в среднем около 2 литров",
    faq_a_good_things: "Вечером (с 18:00) под датой появляется маленькая кнопка: запишите до 3 хороших вещей, которые случились сегодня, — хватит даже одной. Они сохраняются, а в «Прошлых днях» видно, что вы писали раньше. «Не сегодня» скрывает её до завтра, а полностью отключить можно в Настройках > Персонализация и календарь.",
    faq_a_home_countdown: "Отметьте событие ⭐ в календаре (звёздочка рядом с ним в списке событий). Ближайшее отмеченное событие в следующие 100 дней появится под датой — «Через 3 дн. · День рождения мамы», «Завтра · …» или «Сегодня · …». Нажмите на него, чтобы перейти к этому дню в календаре.",
    faq_a_home_streak: "Это сколько дней подряд у вас была хотя бы одна ✓ — что угодно в разделах «Мой день», «Мой распорядок», «Мои цели» или New Me. Показывается начиная с 2 дней. Если сегодня ✓ ещё нет, серия не прервана — впереди весь день. А если она закончится, то просто тихо исчезнет, без чувства вины.",
    faq_a_home_weather: "Включите «Погода в небе главного экрана» в Настройках > Персонализация и календарь и разрешите доступ к местоположению. Тогда небо главного экрана показывает настоящую погоду там, где вы, – солнце (а ночью луну и звёзды), облака, дождь, снег, грозу или туман – в любой теме, с обновлением примерно каждые 40 минут. Примерное местоположение (округлённое примерно до 1 км) остаётся только на вашем устройстве и проверяется через наш сервер у MET Norway. По умолчанию выключено. Под переключателем написано, какая погода сейчас на улице – например ⛅ Переменная облачность, поэтому на небе и солнце, и облака.",
    faq_q_good_things: "Что такое «3 хорошие вещи за сегодня»?",
