    faq_a_home_focus: "Нажмите ◎ вверху главного экрана: исчезает всё, кроме одного дела на сейчас – того, что идёт в этот час, или следующего из списка на сегодня – с большой ✓ и быстрой заметкой. После ✓ появляется следующее. «Режим фокуса ✕» вверху возвращает всё обратно.",
    faq_a_home_search: "Откройте меню ☰ — поиск в самом верху. Введите хотя бы 2 буквы: результаты из заметок, списка покупок, календаря, рецептов, тетрадей (названия и текст страниц), целей, таблиц и книг, по группам — нажмите на результат, чтобы сразу перейти к нему.",
    faq_a_my_day: "«Мой день» объединяет то, что раньше было «Взгляд на сегодня» и «Мой распорядок», в одну ленту времени. Внизу главного экрана видно, сколько уже сделано, что сейчас или дальше (с быстрой ✓), а рядом с заголовком — стакан воды в одно касание. Нажмите (или потяните вверх), чтобы открыть весь день: вверху то, что без времени, а дальше всё по часам – задачи, события и встречи из календаря, постоянные слоты недели, распорядок на сегодня, маленькие шаги ваших целей и приёмы пищи New Me – с линией «сейчас». Можно фильтровать: задачи, распорядок или встречи и события. ✓ здесь – это та же ✓ везде (Мой распорядок, Мои цели, календарь), и она раскрывает ромашку в уголке. «Изменить распорядок» открывает «Мой распорядок» (он есть и в меню), а «＋ Добавить на сегодня» добавляет задачу на сегодня. Нажатие на заголовок «Мой день» (или на полоску сверху) снова его закрывает.",
