    bag_tasks_general: "📝 Общие задачи",
    faq_a_bag_pockets: "Любую тетрадь, таблицу или задачу можно перенести в другой карман: откройте её окно (🎨 в тетради, ✏️ в таблице или нажмите на задачу) и выберите карман. Чтобы изменить название, значок или цвет кармана, откройте его и нажмите ✏️ рядом с названием. При удалении кармана удаляется всё, что в нём есть, поэтому сначала перенесите то, что хотите сохранить. Примеры, которые приходят с новой сумкой, работают так же – их можно изменить или удалить в любой момент.",
    faq_a_my_bag: "В «Моей сумке» ваши тетради, таблицы и задачи собраны вместе. Каждый карман – это часть жизни: дом, семья, работа, поездка – со своим названием, значком и цветом. Нажмите на карман, и он откроется как папка-регистратор: всё, что в нём есть, на одной странице, а цветные разделители сбоку ведут в другие карманы. ＋ добавляет тетрадь, таблицу (или таблицу, созданную ИИ), задачу или новый карман. Фильтры показывают только тетради, таблицы или задачи, а 🔍 ищет по всему. Карточка ✅ Задачи вверху бесплатна для всех; карманы, тетради и таблицы входят в Премиум.",
    faq_q_bag_pockets: "Как перенести или удалить что-то в «Моей сумке»?",
    faq_q_my_bag: "Что такое «Моя сумка»?",
    premium_benefit_bag: "Моя сумка – карманы со своими тетрадями и таблицами",
    faq_a_goal_library: "В «Моих целях» нажмите ＋ (или тему, если целей ещё нет), чтобы открыть библиотеку целей: 12 тем – здоровье, вес, музыка, учёба, деньги, семья и другие – каждая разбита на направления с готовыми планами. Каждый план показывает этапы по неделям (или челлендж по дням, счёт или цель по весу) и маленький ежедневный шаг. «Начать эту цель» сразу создаёт её, «Сначала изменить» открывает её, чтобы поменять что угодно, а переключатель «Добавить в „Мой распорядок“» ставит ежедневный шаг в распорядок на свободный час (нажмите на время, чтобы выбрать другое) – ✓ в одном месте отмечается и в другом. Можно также искать («гитара», «экзамен»), и «✏️ Своя цель» всегда под рукой. 2 плана в каждой теме бесплатно, а вся библиотека – с Премиум ⭐.",
    faq_q_goal_library: "Что такое библиотека целей и как начать цель по готовому плану?",
