    faq_a_new_me_tour: "Сразу после покупки и короткой анкеты небольшой тур показывает игру: верхнюю панель, следующее задание, инструменты по бокам, челлендж недели, волшебный рюкзак, карту мира, вашего персонажа Me и дверь 1 в тайную комнату. Его можно пройти снова в любой момент в ⚙️ Настройки > 🧭 Тур по New Me – там же можно изменить полное имя из анкеты. До покупки рядом с New Me в меню виден 🔒, а нажатие открывает страницу со всем, что входит.",
