    nm_cert_stat_workouts: "тренировок",
    nm_cert_stat_badges: "достижений",
    faq_a_new_me_advanced: "Продвинутый режим открывается вместе с подарком, после всех 20 челленджей, и включается или выключается в 🎁 Ваш подарок. Он даёт New Me золотой вид, свободное составление меню – каждая замена показывает все варианты без ограничения калорий – и экран 📊 Расширенная статистика: калории за последние 30 дней в сравнении с планом, хорошие дни по дням недели, тренд веса с оценкой, когда будет достигнута цель, средние вечернего чек-ина и история челленджей.",
