    nm_gift_title: "Ваш подарок",
    faq_a_new_me_letter_gift: "В начале New Me (или позже, в разделе «Челленджи») можно написать письмо себе в будущее. После запечатывания его нельзя прочитать или изменить, пока оно не откроется: в бутылке из моря в тайной комнате или когда будут пройдены все 20 челленджей – там же ждёт и подарок.",
    faq_q_new_me_letter_gift: "Что такое письмо из прошлого?",
    faq_a_new_me_challenges: "В 🏆 Челленджах 20 челленджей: 10 больших (например, 5 дней без сахара, неделя без углеводов или минус 4 кг за месяц – каждый день дефицит калорий, тренировка и без сахара) и 10 мини – маленькие привычки на неделю, вроде кофе с корицей без сахара. При выборе челленджа спрашивается, когда начать: сегодня, завтра, на следующей неделе или в другую дату. Большой и мини-челлендж могут идти одновременно. Активный челлендж показывается вверху меню и в разделе «Мой день», с ✓ на день. Каждая неделя челленджа даёт один свободный день (🍕), который его не прерывает, а неотмеченный день считается свободным – отметить можно сегодня и вчера. Некоторые дни отмечаются сами: 20-минутная тренировка в «Отслеживании тренировок» или блюда из меню с ✓. У каждого челленджа есть ⓘ – что именно считается (например, полный список углеводов): в самом челлендже и рядом с ним в разделе «Мой день». Ниже, в разделе 🌱 Личностный рост, есть 48 небольших челленджей на одну неделю (они не входят в эти 20) – см. «Что такое челлендж недели?».",
