    nm_tile_challenges: "Челленджи",
    faq_a_workout_calories: "Да. Для каждой тренировки рассчитывается примерный расход калорий – по типу, длительности и последнему весу (для бега и велосипеда ещё и по скорости, если указано расстояние). Он виден в списке тренировок и в месячной сводке (Сожжено) и добавляется к бюджету калорий этого дня: в Дневнике питания, в Показателях калорий и веса и в кольце New Me. Это оценка, поэтому она показана со знаком ~.",
    faq_q_workout_calories: "Учитываются ли тренировки в калориях за день?",
    faq_a_new_me_flexible_menu: "Да. В анкете и в настройках выбирается число приёмов пищи в день – 2 приёма пищи + перекус / 2 приёма пищи + лёгкий ужин / 2 приёма пищи + перекус + лёгкий ужин, – а ➖ на карточке приёма пищи убирает его (остаются минимум 3); «Вернуть» возвращает. В любом случае калорийность дня не меняется: убранное делится между остальными приёмами пищи, и под каждым видно, сколько к нему добавилось и что можно добавить. ✏️ Изменить открывает текст блюда – измените что угодно (например, без хлеба или с ещё одним яйцом), и ИИ заново посчитает калории и белок. 🔄 Заменить предлагает варианты из меню, ⭐ Сохранённые и ✨ Написать; каждое изменение может быть только на сегодня или с этого дня. А в конце «Весь день» есть ➕ Добавить еду – напишите, что было съедено вне меню, и ИИ посчитает и добавит это в сегодня (✕ удаляет).",
