    vision_focus_ribbon: "🎯 Цель месяца",
    vision_tagline: "Большие цели, маленькие шаги.",
    faq_a_app_tour: "Экскурсия открывается автоматически один раз, при первом входе. Она начинается со своих частей — нажмите на любую, чтобы сразу перейти к ней, — затем показывает все части приложения (главный экран, ИИ-помощник и каждый пункт меню) и пять групп настроек, каждую с коротким пояснением, и заглядывает внутрь некоторых (например, в пример пути к цели, в сумку и в Google Calendar). «Далее» — вперёд, «Назад» — назад, «Пропустить эту часть» — к следующей части, ✕ закрывает экскурсию. Посмотреть её снова можно в любой момент: Настройки > Помощь и использование > Экскурсия по приложению — и продолжить с того места, где вы остановились. «Далее» и «Назад» всегда находятся на одном и том же месте внизу экрана, а на компьютере работают и стрелки на клавиатуре.",
    faq_q_app_tour: "Как снова посмотреть экскурсию по приложению?",
    apptour_done_text: "Есть вопрос? Раздел «Помощь и вопросы» в Настройках ответит на всё, а эта экскурсия всегда доступна в разделе «Помощь и использование».",
    apptour_done_title: "Вот и всё! 🎉",
