    apptour_flow_calendar: "Календарь",
    apptour_connect_text: "То, что вы делаете в одном месте, автоматически обновляет остальные:",
    apptour_connect_title: "Всё связано",
    apptour_s_support_text: "Помощь и вопросы, связь с нами, возможность поделиться приложением – и эта экскурсия в любой момент.",
    apptour_s_account_text: "Премиум, пароль, личный отчёт в PDF, синхронизация с Google Calendar и удаление аккаунта.",
    apptour_s_notifications_text: "Уведомления-напоминания и их звук. Кнопка '⏰ Ещё нет' в напоминании работает как повтор сигнала будильника: напоминает снова каждые 5 минут.",
    apptour_s_personalization_text: "Страна, сколько приёмов пищи и перекусов в день, когда начинается ваш финансовый месяц и что показывать на главном экране.",
