    apptour_m_study_link: "🪄 Умное Разделение в карточке ✅ Задачи разбивает большую задачу на шаги в календаре.",
    apptour_m_study_text: "Ваша сумка: карман для каждой части жизни – а внутри тетради, таблицы и задачи.",
    apptour_m_vision_link: "📅 у этапа добавляет его в календарь; маленькие шаги и задачи челленджа по дням появляются в разделе «Мой день», а прогресс можно отслеживать и по числу или по весу.",
    apptour_m_vision_text: "Ваши цели – это пути из маленьких шагов, а сегодняшние шаги – вверху. Заглянем внутрь 👇",
    apptour_m_myweek_link: "Синхронизируется с Google Calendar (в Настройках).",
    apptour_m_myweek_text: "Календарь на месяц, еженедельные повторяющиеся задачи с напоминаниями и все события с датой. И бумажный ежедневник встреч на неделю 🤝.",
    apptour_m_newme_link: "Всё учитывается в разделах «Дневник питания» и «Мой день»; вес общий с разделом «Показатели калорий и веса».",
    apptour_m_newme_text: "План питания на 1 300 / 1 500 калорий в волшебном игровом мире: меню на сегодня с ✓, замены тремя способами – из меню, из сохранённых блюд или написав ИИ, что вы съели, а он посчитает калории – список покупок, напоминания о еде и путь прогресса с достижениями, замерами и фото. А ещё 🏆 20 челленджей – с подарком в конце – и челлендж недели.",
    apptour_ai_table_text: "Опишите, какая таблица нужна, – ИИ продумает её столбцы (Премиум).",
    apptour_ai_photo_link: "Сохраняется в разделе «Мои рецепты».",
    apptour_ai_photo_text: "Сфотографируйте написанный рецепт – ИИ заполнит новый рецепт за вас.",
    apptour_ai_schedule_link: "Они появятся в календаре и в разделе «Мой день».",
    apptour_ai_schedule_text: "Опишите планы простыми словами, разовые или повторяющиеся, – они сразу попадут в календарь.",
    apptour_ai_food_link: "Сразу попадает в Дневник питания и в итог за сегодня.",
    apptour_ai_food_text: "Напишите, что вы съели, – калории рассчитаются и запишутся сами.",
    apptour_newme_short_text: "Открывает New Me – меню на сегодня прямо на главном экране.",
    apptour_ai_link: "Маленький значок 1 на кнопке – это ежедневное напоминание «что самое важное сегодня».",
    apptour_ai_text: "Пишите простыми словами – помощник сделает остальное: запишет калории, внесёт планы в календарь, прочитает рецепт с фото и построит таблицы.",
    apptour_quicknote_link: "📝 и 🛒 открывают полные списки; 🍎 записывает сохранённое блюдо в Дневник питания.",
    apptour_quicknote_text: "Быстро запишите что угодно – в Заметки или сразу в Список покупок.",
    apptour_routine_link: "Привычка может автоматически записать тренировку в раздел «Отслеживание тренировок».",
    apptour_routine_text: "Ваш распорядок дня по часам, во вкладках (дети, учёба, работа…). Отмечайте ✓ каждый день, чтобы формировать привычки и серии; 📅 показывает весь месяц.",
    apptour_premium_text: "Открывает полный AI-ассистент, темы, шрифты, «Мою сумку» и многое другое.",
    apptour_note_text: "Стикер на всю неделю. Внутри шестерёнка ⚙ добавляет чек-лист из 1–3 строк и меняет цвет и стиль заметки.",
    apptour_peek_link: "Сюда попадают задачи от ИИ, из календаря и Google Calendar, шаги целей – а также калории за сегодня 🔥 и ваша 🎯 цель месяца.",
    apptour_peek_text: "Всё, что происходит сегодня, в одном месте: задачи, встречи, распорядок и маленькие шаги на одной ленте времени. Отмечайте ✓ прямо здесь.",
    apptour_date_text: "Нажмите, чтобы быстро открыть календарь на месяц – и сразу что-нибудь добавить.",
