    table_select_option_delete_title: "Удалить вариант",
    faq_a_other_manual_option: "Везде, где нужно выбрать из списка вариантов, есть также '✏️ Другое' - выберите его и введите именно то, что нужно. В таблице со столбцом выбора (например, 'Родство' в таблице подарков) нажмите на ячейку, выберите '✏️ Другое', введите значение (например, 'Племянник') и нажмите Добавить - оно сохранится как новый вариант этого столбца, и в следующий раз уже будет в списке. Маленький × рядом с каждым вариантом в этом списке удаляет вариант из столбца. При выборе значка таблицы доступно множество значков (в том числе цветные стикеры). Так же это работает для категорий сохранённых блюд, категорий рецептов, категорий регулярных расходов (сохраняется как новая личная категория) и категорий целей в разделе «Мои цели».",
