    faq_a_receipts_total: "На экране «Счета-фактуры / Чеки» нажмите 🧮 «Итого по всем чекам». Выберите, с какого по какой год (по умолчанию - от самого старого чека до текущего года), нажмите «Рассчитать», и появится общая сумма обеих категорий вместе - Домашние расходы и Деловые расходы - а также количество чеков и сумма по каждой категории отдельно.",
