    nm_drinks_hint: "Достаточно ввести название напитка – калории рассчитываются автоматически, а число можно изменить.",
    nm_slot_drinks: "Напитки",
    faq_a_new_me_tracking: "Нажмите на следующее задание вверху New Me, а затем на ✓ Съедено, чтобы отметить, что следующий приём пищи съеден, – полное меню с ✓ у каждого приёма пищи есть во «Весь день» сбоку, а сегодняшние приёмы пищи видны и в «Моём дне» на главном экране – нажатие на один из них там (или наведение мыши) показывает, что именно съесть, с ✓ и «Заменить». Всё синхронизируется с «Дневником питания»: приёмы пищи по плану, напитки и всё, что добавлено в другом месте (например, кофе из быстрого добавления), учитываются вместе в New Me и в «Моём дне» – ничего уже введённого не перезаписывается, а снятие ✓ убирает только часть New Me. Когда все приёмы пищи на сегодня отмечены, бывает маленький праздник. В «Напитках» записываются напитки за день – все вместе до ~150 ккал, то есть примерно 3 напитка до ~50 ккал каждый. Достаточно ввести название напитка – калории заполнятся автоматически с помощью ИИ. В двух строках кофе/чай есть ещё поле «Молоко? Сколько?» (например, «немного» или «50 мл»), и расчёт обновляется; число можно изменить и до добавления, и после. Напиток с названием и калориями сохраняется автоматически, как только вы переходите дальше, – нажимать «Добавить» не обязательно. Нажмите ☆ рядом с напитком, чтобы сохранить его как постоянный – постоянные напитки появляются кнопками вверху карточки «Напитки», и одно нажатие добавляет их в день. ⭐ сохраняет приём пищи как сохранённое блюдо. «Таблица за день» показывает, что съедено, с калориями и белком. Маленький 💎 рядом с режимом фокуса вверху главного экрана открывает его напрямую. Значения калорий и белка – оценки ИИ и могут содержать ошибки. Съедено не всё? Под отмеченным приёмом пищи кнопка «Съедено не всё?» убирает четверть, половину или три четверти порции – или то, что вы напишете, с расчётом, – и калории за день обновляются.",
    faq_q_new_me_tracking: "Как в New Me работают ✓, замены и калории?",
    faq_a_new_me_what: "New Me – отдельная программа ежедневного меню с двумя готовыми планами – 1 300 или 1 500 калорий – из 2 основных приёмов пищи и 2 перекусов, по 3 варианта на каждый. В неё входит весь Премиум. Цена: $11.99 в месяц (отмена в любой момент) или $99.99 один раз – навсегда. Открывается через 💎 New Me в меню. Перед началом есть короткая анкета, которая начинается с медицинского предупреждения, которое нужно принять. Программа – это только общая информация, она не заменяет врача или клинического диетолога.",
