    daily_focus_modal_title: "🧠 Что для вас самое важное сделать сегодня?", daily_focus_modal_subtitle: "Ответьте, и это сразу добавится в расписание на сегодня.", daily_focus_input_placeholder: "Сегодня я больше всего хочу", daily_focus_save_btn: "Добавить в расписание на сегодня", daily_focus_skip_btn: "Не сейчас", daily_focus_missing_text: "Сначала напишите что-нибудь", daily_focus_added_toast: "Добавлено в расписание на сегодня", daily_focus_other_option: "✍️ Другое...",
    daily_focus_c1_d0: "Беречь своё тихое пространство от шума вокруг", daily_focus_c1_d1: "Устанавливать чёткие границы - с любовью и без чувства вины", daily_focus_c1_d2: "Оставаться на своём якоре, даже когда вокруг буря", daily_focus_c1_d3: "Ставить своё спокойствие и энергию на первое место", daily_focus_c1_d4: "Не брать на себя чужие эмоции и настроения", daily_focus_c1_d5: "Не позволять чужим словам поколебать мою самооценку",
    daily_focus_c2_d0: "Прислушиваться к тому, что нужно моему телу и разуму", daily_focus_c2_d1: "Радоваться маленьким моментам по пути", daily_focus_c2_d2: "Замедлиться и по-настоящему настроиться на себя", daily_focus_c2_d3: "Давать себе пространство, чтобы дышать посреди дел", daily_focus_c2_d4: "Чувствовать себя дома и в мире с собой", daily_focus_c2_d5: "Сосредоточиться на том, что происходит сейчас, не торопясь вперёд",
    daily_focus_c3_d0: "Говорить мягко, терпеливо и с пониманием", daily_focus_c3_d1: "Не принимать ничего на свой счёт", daily_focus_c3_d2: "Не додумывать - просто спросить или отпустить", daily_focus_c3_d3: "Доверять своему темпу и своему пути", daily_focus_c3_d4: "Отпустить стремление к идеалу и выбрать движение вперёд", daily_focus_c3_d5: "Быть терпеливой к своему собственному процессу",
    daily_focus_c4_d0: "Закончить день с чувством гордости и удовлетворения", daily_focus_c4_d1: "Замечать свой прогресс, даже в маленьких шагах", daily_focus_c4_d2: "Сосредотачиваться на одной задаче за раз", daily_focus_c4_d3: "Навести порядок в делах и действовать спокойно", daily_focus_c4_d4: "Принимать себя такой, какая я есть сегодня", daily_focus_c4_d5: "Знать, когда действовать, а когда отпустить",
