    daily_focus_p1_d6_s1: "Сохранять свою самооценку устойчивой и крепкой", daily_focus_p1_d6_s2: "Сосредотачиваться на настоящем моменте и наслаждаться им", daily_focus_p1_d6_s3: "Сохранять терпение и полностью доверять своему процессу", daily_focus_p1_d6_s4: "Знать, когда действовать, а когда мягко отпускать", daily_focus_p1_d6_s5: "Возвращать себе здоровое и доброе чувство меры во всём",
    daily_focus_p1_d7_s1: "Создавать достойное пространство для глубокого, успокаивающего отдыха", daily_focus_p1_d7_s2: "Слушать свою внутреннюю тишину и позволять телу расслабиться", daily_focus_p1_d7_s3: "Окружать себя добрыми словами и приятными мыслями", daily_focus_p1_d7_s4: "Отпускать все дела и посвящать себя качественному времени", daily_focus_p1_d7_s5: "Наполнять сердце благодарностью за пройденный путь",
    daily_focus_p2_d1_s1: "Хранить тишину и порядок в своём рабочем пространстве", daily_focus_p2_d1_s2: "Прислушиваться к потребностям дня и расставлять приоритеты", daily_focus_p2_d1_s3: "Выбирать воодушевляющий внутренний диалог, который побуждает к действию", daily_focus_p2_d1_s4: "Начинать сразу с главной задачи и создавать импульс", daily_focus_p2_d1_s5: "Открывать день с решимостью и настроем на успех",
    daily_focus_p2_d2_s1: "Сосредотачиваться на своём расписании и уделять время главному", daily_focus_p2_d2_s2: "Действовать исходя из чёткого и ясного решения", daily_focus_p2_d2_s3: "Гибко реагировать на изменения и быстро возвращаться на курс", daily_focus_p2_d2_s4: "Выбирать последовательность в задачах и укреплять дисциплину", daily_focus_p2_d2_s5: "Ценить усилия, которые я вкладываю в то, чтобы держать своё слово",
    daily_focus_p2_d3_s1: "Оставаться на связи со своими целями и углублять концентрацию", daily_focus_p2_d3_s2: "Замедляться, чтобы действовать с максимальной точностью и качеством", daily_focus_p2_d3_s3: "Сохранять полную ясность в каждом разговоре и согласовании", daily_focus_p2_d3_s4: "Сосредотачиваться на одном деле до его полного завершения", daily_focus_p2_d3_s5: "Быстро извлекать урок из каждого вызова и двигаться дальше",
    daily_focus_p2_d4_s1: "Держать точный рабочий темп, который создаёт высокую энергию", daily_focus_p2_d4_s2: "Делать осознанные перерывы, чтобы обострить концентрацию", daily_focus_p2_d4_s3: "Доверять своему рабочему плану и придерживаться его", daily_focus_p2_d4_s4: "Разбивать большую задачу на простые и упорядоченные шаги", daily_focus_p2_d4_s5: "Признавать прекрасный прогресс, достигнутый за последние дни",
    daily_focus_p2_d5_s1: "Поддерживать свой высокий стандарт и качество исполнения", daily_focus_p2_d5_s2: "Наполнять голову практическими действиями, которые продвигают меня вперёд", daily_focus_p2_d5_s3: "Выбирать завершать задачи с простотой и лёгкостью", daily_focus_p2_d5_s4: "Закрывать незавершённые дела и заканчивать задачи с ясной головой", daily_focus_p2_d5_s5: "Доверять своей самодисциплине, которая становится всё крепче",
    daily_focus_p2_d6_s1: "Поддерживать правильный баланс между работой и отдыхом", daily_focus_p2_d6_s2: "Подводить итог последним дням с присутствием и извлечёнными уроками", daily_focus_p2_d6_s3: "Сохранять терпение к процессу, который строится шаг за шагом", daily_focus_p2_d6_s4: "Ценить всё, что удалось сделать, и спокойно расслабляться", daily_focus_p2_d6_s5: "Наполняться чувством удовлетворения от проявленной дисциплины",
    daily_focus_p2_d7_s1: "Посвятить день восстановлению сил и полному обновлению", daily_focus_p2_d7_s2: "Прислушиваться к внутреннему желанию и делать то, что меня наполняет", daily_focus_p2_d7_s3: "От всего сердца хвалить себя за настойчивость и пройденный путь", daily_focus_p2_d7_s4: "Отпускать все планы и наслаждаться свободой мыслей", daily_focus_p2_d7_s5: "Испытывать благодарность за способность двигаться настойчиво, учиться и совершенствоваться",
    faq_q_daily_focus_prompt: "Что за маленькое напоминание спрашивает, что мне важнее всего сделать сегодня?", faq_a_daily_focus_prompt: "Это ежедневное Premium-напоминание: раз в день на значке ИИ-ассистента появляется маленький значок «1». Нажмите на него, чтобы открыть облачко с вопросом, что для вас сегодня важнее всего, и в нём сразу видны 5 готовых вариантов (они меняются каждый день и чередуют темы в течение целого года, чтобы не повторяться) и 'Другое', чтобы написать свой - можно выбрать несколько. Нажмите Добавить, и выбранное появится в виде маленьких ярлыков-напоминаний вверху 'Мой день' (это не задачи для отметки). Если закрыть его через ✕ или нажать мимо, значок до конца дня просто становится бледнее, а не исчезает. По умолчанию напоминание включено, но его можно отключить в Настройках > Персонализация и календарь. Сегодня не тот день? Нажмите «🌙 Не сегодня» – значок исчезнет до завтра, а потом вопрос вернётся как обычно. Одно из предложений берётся из вашей жизни – следующий шаг цели месяца или сегодняшнее чтение. Каждый день начинается заново.",
