    habits_title: "Привычки", habits_empty_hint: "Пока нет привычек - добавьте одну, чтобы начать отслеживать серию.", habits_add_modal_title: "Новая привычка", habits_name_placeholder: "напр. Пить воду, Читать, Медитировать...", habits_missing_name: "Пожалуйста, дайте привычке название", habits_delete_title: "Удалить эту привычку?", habits_delete_confirm: "Это также навсегда удалит всю её историю и серию.", habits_link_sport_label: "Также записывать это как тренировку при выполнении", habits_sport_duration_placeholder: "Продолжительность в минутах", habits_missing_sport_duration: "Введите продолжительность в минутах", habit_auto_logged_sport_badge: "Из привычки", habits_overview_btn_title: "Обзор за месяц", habits_overview_title: "Привычки - Обзор за месяц", routine_goals_section_title: "🎯 Цели и привычки", routine_goals_empty_hint: "В этой вкладке пока ничего нет - добавьте пункты в распорядок, чтобы отслеживать их здесь.", routine_goals_toggle_label: "Показывать отслеживание целей и привычек",
